solutionCode:
pub fn chama(nome: &str, fila: &mut i32, chegaram: i32) -> String {
    *fila = *fila + chegaram;
    let mut espacos = 0;
    for letra in nome.chars() {
        if letra.to_string() == " " {
            espacos += 1;
        }
    }
    let sigla = &nome[0..2];
    format!("{} entrou na fila {} (espacos: {})", sigla, *fila, espacos)
}

testsCode:
use desafio::chama;

#[test]
fn testa_a_fila_da_ana() {
    let mut fila = 4;
    assert_eq!(chama("ana", &mut fila, 2), "an entrou na fila 6 (espacos: 0)");
    assert_eq!(fila, 6);
}

#[test]
fn testa_a_fila_do_bo_e_da_clara() {
    let mut fila = 0;
    let dono = String::from("bo clara");
    assert_eq!(chama(&dono, &mut fila, 3), "bo entrou na fila 3 (espacos: 1)");
    assert_eq!(fila, 3);
}
